sequenceDiagram(name = "Checkout Process") {
    val customer = lifeline(name = "Customer") { isActor = true }
    val shop = lifeline(name = "Shop")
    val checkout = lifeline(name = "Checkout Service")
    val gateway = lifeline(name = "Payment Gateway")
    val db = lifeline(name = "Database")

    message(from = customer, to = shop, label = "initiateCheckout()")
    message(from = shop, to = checkout, label = "startCheckout()")
    message(from = checkout, to = gateway, label = "verifyPaymentDetails()")
    reply(from = gateway, to = checkout, label = "verificationResult")

    alt {
        branch(guard = "[valid]") {
            message(from = checkout, to = db, label = "saveOrder()")
            reply(from = db, to = checkout, label = "orderSaved")
            message(from = checkout, to = gateway, label = "processPayment()")
            reply(from = gateway, to = checkout, label = "paymentProcessed")
        }
        branch(guard = "[invalid]") {
            message(from = checkout, to = shop, label = "rejectWithError()")
        }
    }

    reply(from = checkout, to = shop, label = "checkoutResult")
    reply(from = shop, to = customer, label = "displayResult")
}

